 {page==='Tagihan'&&(()=>{const monthNow=new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Jakarta'}).slice(0,7);const monthInvoices=invoices.filter(i=>String(i.period_month||'')===monthNow);return <><div className="stats compact-stats invoice-stats"><Stat title="Tagihan Belum Lunas Bulan Ini" value={money(monthInvoices.filter(i=>['unpaid','partial'].includes(i.status)).reduce((n,i)=>n+Number(i.amount-i.paid_amount),0))} note={`${monthInvoices.filter(i=>['unpaid','partial'].includes(i.status)).length} tagihan`} icon={Receipt} onClick={()=>setInvoiceFilter('unpaid')} active={invoiceFilter==='unpaid'}/><Stat title="Tagihan Lunas Bulan Ini" value={money(monthInvoices.filter(i=>i.status==='paid').reduce((n,i)=>n+Number(i.amount),0))} note={`${monthInvoices.filter(i=>i.status==='paid').length} tagihan`} icon={CreditCard} onClick={()=>setInvoiceFilter('paid')} active={invoiceFilter==='paid'}/><Stat title="Total Tagihan Bulan Ini" value={monthInvoices.length} note="Hanya periode berjalan" icon={FileSpreadsheet} onClick={()=>setInvoiceFilter('all')} active={invoiceFilter==='all'}/></div><section className="panel"><div className="panel-head"><div><h3>Tagihan Bulan Ini</h3><p>Periode {monthNow} · Tagihan bulan lain disembunyikan dari halaman ini</p></div><button className="primary" onClick={generate}><Plus size={17}/> Generate Tagihan</button></div><div className="toolbar"><div className="search"><Search size={17}/><input placeholder="Cari nomor tagihan, nama atau kode pelanggan..." value={invoiceSearch} onChange={e=>setInvoiceSearch(e.target.value)}/></div><label className="filter-select"><span>Status tagihan</span><select value={invoiceFilter} onChange={e=>setInvoiceFilter(e.target.value)}><option value="all">Semua status</option><option value="unpaid">Belum lunas / sebagian</option><option value="paid">Lunas</option></select></label></div><InvoiceTable rows={monthInvoices.filter(i=>(invoiceFilter==='all'||(invoiceFilter==='unpaid'?['unpaid','partial'].includes(i.status):i.status===invoiceFilter))&&`${i.invoice_number} ${i.customer_name} ${i.customer_code}`.toLowerCase().includes(invoiceSearch.toLowerCase()))} onPay={payment} onPrint={printInvoiceThermal} onPrintPaid={printInvoiceReceipt} onDelete={async invoice=>{if(!window.confirm(`Hapus tagihan ${invoice.invoice_number}? Pembayaran yang terkait juga akan dihapus. Tindakan ini tidak dapat dibatalkan.`))return;try{await api(`/invoices/${invoice.id}`,{method:'DELETE'});setNotice(`Tagihan ${invoice.invoice_number} dihapus.`);load();if(page==='Pembayaran')loadPaymentHistory(paymentMonth)}catch(e){setError(e.message)}}} onNunggak={async invoice=>{try{const skip=!Boolean(invoice.skip_isolation);await api(`/invoices/${invoice.id}/nunggak`,{method:'PUT',body:JSON.stringify({skip})});setNotice(skip?`NUNGGAK diaktifkan untuk ${invoice.invoice_number}; isolir bulan ini dilewati.`:`Pengecualian NUNGGAK dihapus untuk ${invoice.invoice_number}.`);load()}catch(e){setError(e.message)}}}/></section></>})()}
